import { MarketingArtwork, MarketingAtmosphere, MarketingChoices, MarketingCopy, MarketingEmailCapture, MarketingFrame as StoryFrame, type MarketingHeading, type MarketingLink, type MarketingMark, type MarketingSelectionProps, MarketingMarks, MarketingNav, PlaybackButtons, useMarketingPlayback, useMarketingSelection } from "@/components/motion/marketing-story";

function MarketingFrame({ children, className, centered }: { children: ReactNode; className?: string; centered?: boolean }) {
  return <StoryFrame centered={centered} className={cn("py-16 sm:px-8 sm:py-20 lg:py-20 [&_[data-marketing-copy]>h2]:text-5xl [&_[data-marketing-copy]>h2]:font-medium [&_[data-marketing-copy]>h2]:leading-[0.94] [&_[data-marketing-copy]>h2]:tracking-[-0.045em] sm:[&_[data-marketing-copy]>h2]:text-6xl", className)}>{children}</StoryFrame>;
}

export interface HeroNavigation { brand: MarketingLink; links?: MarketingLink[] }
export interface HeroMetric { label: string; value: string; detail?: string }
export interface HeroReport {
  id: string; name: string; metrics: HeroMetric[];
  comparison: { label: string; current: number; previous: number }[];
  sources: { label: string; value: string }[];
  brief: string;
}
function MetricStrip({ metrics }: { metrics: HeroMetric[] }) {
  return <dl className="grid gap-4 sm:grid-cols-3">{metrics.map(metric => <div key={metric.label} className="rounded-2xl border border-border bg-background/80 p-4"><dt className="text-xs text-muted-foreground">{metric.label}</dt><dd className="mt-2 text-2xl font-semibold tabular-nums">{Number.isFinite(Number(metric.value)) && metric.value.trim() ? <><span className="sr-only">{metric.value}</span><span aria-hidden="true"><AnimatedNumber value={Number(metric.value)} startOnView={false}/></span></> : metric.value}</dd>{metric.detail && <dd className="mt-1 text-xs text-muted-foreground">{metric.detail}</dd>}</div>)}</dl>;
}
function Comparison({ rows }: { rows: HeroReport["comparison"] }) {
  const [active, setActive] = useState<number | null>(null);
  const max = Math.max(1, ...rows.flatMap(row => [row.current, row.previous]));
  const current = rows.map((row, index) => `${index * 600 / Math.max(1, rows.length - 1)},${200 - Math.max(0, row.current) / max * 170}`).join(" ");
  const previous = rows.map((row, index) => `${index * 600 / Math.max(1, rows.length - 1)},${200 - Math.max(0, row.previous) / max * 170}`).join(" ");
  return <div className="relative min-w-0 rounded-2xl border border-border bg-background p-5"><div className="flex flex-wrap justify-between gap-2"><h4 className="text-sm font-medium">A connected view of your progress</h4><p className="text-[10px] text-muted-foreground"><span aria-hidden className="mr-1 inline-block size-1.5 rounded-full bg-foreground"/>This period <span aria-hidden className="mx-1 inline-block size-1.5 rounded-full bg-muted-foreground/30"/>Previous period</p></div><div className="relative mt-6"><svg role="img" aria-label="Current and previous period comparison" viewBox="0 0 600 230" className="h-64 w-full overflow-visible text-foreground" onPointerMove={event => { const rect = event.currentTarget.getBoundingClientRect(); setActive(Math.max(0, Math.min(rows.length - 1, Math.round((event.clientX - rect.left) / rect.width * (rows.length - 1))))); }} onPointerLeave={() => setActive(null)}><g stroke="currentColor" strokeOpacity="0.06">{[30, 85, 140, 200].map(y => <path key={y} d={`M0 ${y}H600`}/>)}</g><polygon points={`0,200 ${current} 600,200`} fill="currentColor" opacity="0.04"/><polyline points={previous} fill="none" stroke="currentColor" strokeOpacity="0.2" strokeWidth="2" strokeDasharray="4 5"/><polyline points={current} fill="none" stroke="currentColor" strokeWidth="2.5"/>{active !== null && rows[active] && <g><path d={`M${active * 600 / Math.max(1, rows.length - 1)} 20V200`} stroke="currentColor" strokeOpacity="0.2"/><circle cx={active * 600 / Math.max(1, rows.length - 1)} cy={200 - rows[active].current / max * 170} r="5" fill="currentColor"/></g>}</svg>{active !== null && rows[active] && <div role="status" className="pointer-events-none absolute left-1/2 top-2 -translate-x-1/2 rounded-xl border border-border bg-background px-3 py-2 text-xs shadow-sm">{rows[active].label} · {rows[active].current} / {rows[active].previous}</div>}</div><div className="flex justify-between gap-1">{rows.map((row, index) => <button type="button" key={row.label} onFocus={() => setActive(index)} onBlur={() => setActive(null)} className="min-h-11 rounded-lg text-[10px] text-muted-foreground focus-visible:outline-2">{row.label}<span className="sr-only">: current {row.current}, previous {row.previous}</span></button>)}</div></div>;
}
export interface AnalyticsFlowHeroProps extends MarketingHeading { reports: HeroReport[]; value?: string; onValueChange?: (id: string) => void }
export function AnalyticsFlowHero({ reports, value, onValueChange, className, ...heading }: AnalyticsFlowHeroProps) {
  const [selected, select] = useMarketingSelection(reports.map(report => report.id), value, onValueChange);
  const [brief, setBrief] = useState<string | null>(null);
  const report = reports.find(item => item.id === selected);
  const openReport = reports.find(item => item.id === brief);
  return <MarketingFrame centered className={className}><MarketingAtmosphere kind="ribbons"/><MarketingCopy {...heading} className="mx-auto max-w-3xl"/><p className="mt-6 text-xs text-muted-foreground">{reports.length} reports. One connected view.</p><div className="relative z-10 mx-auto mt-12 max-w-5xl overflow-hidden rounded-3xl border border-border bg-background/90 text-left shadow-[0_16px_80px_-50px_rgb(0_0_0/0.25)]"><div className="flex flex-wrap items-center justify-between gap-4 border-b border-border px-5 py-4 sm:px-7"><div><p className="text-sm font-medium">Analytics workspace</p><p className="mt-1 text-xs text-muted-foreground">Sample report</p></div><MarketingChoices label="Analytics report" items={reports.map(item => ({ id: item.id, label: item.name }))} value={selected} onChange={select}/></div>{report ? <div className="space-y-5 p-5 sm:p-7"><h3 className="text-xl font-medium">{report.name}</h3><MetricStrip metrics={report.metrics}/><div className="grid items-start gap-4 lg:grid-cols-[1.8fr_1fr]"><Comparison rows={report.comparison}/><aside className="rounded-2xl border border-border p-5"><h4 className="text-sm font-medium">Where they found you</h4><p className="mt-1 text-xs text-muted-foreground">Share of sessions</p><dl className="mt-6 space-y-5">{report.sources.map((source, index) => <div key={source.label} className="flex items-center justify-between gap-3 text-xs"><dt className="flex items-center gap-2"><span aria-hidden className="size-2 rounded-sm bg-foreground" style={{ opacity: 1 - index * 0.18 }}/>{source.label}</dt><dd className="font-mono">{source.value}</dd></div>)}</dl><div className="mt-8 rounded-xl bg-muted/50 p-4"><p className="text-xs font-medium">A useful next step</p><p className="mt-2 text-xs leading-6 text-muted-foreground">{report.brief}</p><Button className="mt-3" size="sm" variant="outline" onClick={() => setBrief(report.id)}>Read insight brief</Button></div></aside></div><p className="border-t border-border pt-4 text-[10px] text-muted-foreground">Illustrative data · Try a report or explore the chart</p></div> : <p role="status" className="p-6">No reports available.</p>}</div><MorphingModal viewId={openReport?.id ?? null} onClose={() => setBrief(null)} placement="center"><h3 className="text-lg font-medium">{openReport?.name} insight brief</h3><p className="mt-3 text-sm leading-relaxed text-muted-foreground">{openReport?.brief}</p><Button className="mt-5" onClick={() => setBrief(null)}>Close brief</Button></MorphingModal></MarketingFrame>;
}

export interface HeroTeammate { id: string; name: string; role: string; avatar?: string; color?: string; task: string; activity: string[]; messages: { author: string; text: string }[]; sources: MarketingLink[]; brief: string }
function TeammatePortrait({ teammate, index, large = false }: { teammate: HeroTeammate; index: number; large?: boolean }) {
  const reduce = useReducedMotion();
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref);
  return <motion.span ref={ref} aria-hidden animate={large && inView && !reduce ? { y: [0, -9, 0], rotate: [index % 2 ? -5 : 5, index % 2 ? 5 : -5, index % 2 ? -5 : 5] } : undefined} transition={{ duration: 5 + index, repeat: Infinity, ease: "easeInOut" }} className={cn("relative inline-flex shrink-0 items-center justify-center overflow-hidden bg-gradient-to-br from-white/30 to-black/10 shadow-[inset_0_2px_6px_rgb(255_255_255/0.4)]", large ? "size-20 text-4xl sm:size-28 lg:size-32" : "size-8 text-xs", index % 3 === 0 ? "rounded-[45%_55%_48%_52%]" : index % 3 === 1 ? "rounded-[30%_35%_40%_30%]" : "rounded-[50%_50%_25%_25%]")} style={{ backgroundColor: teammate.color ?? ["#7ab99c", "#dfb86b", "#78abc8"][index % 3] }}>{teammate.avatar ?? <span className={cn("absolute left-[48%] top-[30%] flex rotate-[-12deg] gap-2", !large && "gap-0.5")}><span className={cn("rounded-full bg-white/90", large ? "h-5 w-2.5" : "h-1.5 w-0.5")}/><span className={cn("rounded-full bg-white/90", large ? "h-5 w-2.5" : "h-1.5 w-0.5")}/></span>}</motion.span>;
}
export interface AiTeammatesHeroProps extends MarketingHeading, MarketingSelectionProps { teammates: HeroTeammate[] }
export function AiTeammatesHero({ teammates, value, onValueChange, className, ...heading }: AiTeammatesHeroProps) {
  const searchId = useId();
  const [query, setQuery] = useState("");
  const [selected, select] = useMarketingSelection(teammates.map(item => item.id), value, onValueChange);
  const [brief, setBrief] = useState(false);
  const teammate = teammates.find(item => item.id === selected);
  const playback = useMarketingPlayback(teammate?.activity.length ?? 0);
  const filtered = teammates.filter(item => `${item.name} ${item.role}`.toLowerCase().includes(query.toLowerCase()));
  return <MarketingFrame className={className}><div className="relative grid items-center gap-6 lg:grid-cols-[0.95fr_1.05fr] lg:gap-12"><MarketingCopy {...heading}/><div className="relative isolate grid min-h-96 grid-cols-3 items-center gap-3 px-4 py-16"><MarketingAtmosphere webgl/>{teammates.map((item, index) => <button key={item.id} type="button" aria-label={`Meet ${item.name}, ${item.role}`} aria-pressed={selected === item.id} onClick={() => { select(item.id); playback.select(0); }} className="relative flex min-w-0 flex-col items-center gap-4 rounded-2xl py-4 text-center focus-visible:outline-2"><TeammatePortrait teammate={item} index={index} large/><span className="rounded-full border border-border bg-background/80 px-3 py-1 text-sm">{item.name} {selected === item.id && <span aria-hidden>↓</span>}</span><small className="text-xs text-muted-foreground">{item.role}</small></button>)}</div></div><div ref={playback.ref} className="relative z-10 mt-12 grid overflow-hidden rounded-3xl border border-border bg-background sm:grid-cols-[15rem_1fr]"><aside className="border-b border-border sm:border-b-0 sm:border-r"><div className="border-b border-border px-5 py-5 text-sm font-medium">Your AI team <span className="float-right rounded-full bg-muted px-2 py-1 text-[10px] font-normal text-muted-foreground">Demo</span></div><div className="p-4"><label className="sr-only" htmlFor={searchId}>Search teammates</label><input id={searchId} value={query} onChange={event => setQuery(event.target.value)} className="mb-6 w-full min-w-0 rounded-full border border-border bg-background px-3 py-2 text-xs" placeholder="Find a teammate"/><p className="mb-3 font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Your team</p><div className="space-y-2">{filtered.map((item, index) => <button key={item.id} type="button" aria-label={`Open ${item.name} conversation`} aria-pressed={selected === item.id} onClick={() => { select(item.id); playback.select(0); }} className={cn("flex w-full items-center gap-3 rounded-2xl border px-3 py-4 text-left text-xs", selected === item.id ? "border-border bg-muted/20 shadow-sm" : "border-transparent hover:bg-muted/30")}><TeammatePortrait teammate={item} index={index}/><span>{item.name}<small className="mt-1 block text-[10px] text-muted-foreground">{item.role}</small></span></button>)}{!filtered.length && <p role="status" className="text-sm text-muted-foreground">No teammates match your search.</p>}</div></div></aside>{teammate && <div className="min-w-0"><header className="flex items-center gap-3 border-b border-border px-5 py-4"><TeammatePortrait teammate={teammate} index={teammates.indexOf(teammate)}/><div><h3 className="text-sm font-medium">{teammate.name}</h3><p className="mt-1 text-[10px] text-muted-foreground">{teammate.role}</p></div></header><div className="min-h-96 px-5 py-6 sm:px-8"><p className="mb-6 text-center text-[10px] text-muted-foreground">Sample task · A little help from {teammate.name}</p><ol className="space-y-6">{withOccurrenceKeys(teammate.messages, message => JSON.stringify([message.author, message.text])).slice(0, playback.index + 1).map(({ item: message, key }, index) => <li key={key} className={cn("max-w-[90%] rounded-2xl border border-border p-4 text-sm leading-6", index % 2 ? "ml-auto bg-foreground text-background" : "bg-background shadow-sm")}><strong className="mb-2 block text-[10px] font-medium">{message.author}</strong>{message.text}</li>)}</ol><ol className="mt-5 space-y-2">{teammate.activity.map((activity, index) => <li key={activity} className="flex items-center gap-2 text-xs leading-6 text-muted-foreground"><span aria-hidden>{index < playback.index ? "✓" : index === playback.index ? "•" : "○"}</span>{activity}</li>)}</ol><div className="mt-6 flex flex-wrap gap-2">{teammate.sources.map(source => <a key={source.href} href={source.href} className="rounded-full border border-border px-3 py-1 text-[10px] text-muted-foreground hover:underline">{source.label}</a>)}</div><Button className="mt-5" size="sm" variant="outline" onClick={() => setBrief(true)}>Review finished brief</Button></div><footer className="border-t border-border px-5 py-4"><p className="text-xs">{teammate.task}</p><PlaybackButtons playing={playback.playing} onToggle={() => playback.setPlaying(!playback.playing)} onRestart={() => playback.select(0)} onNext={() => playback.select((playback.index + 1) % Math.max(1, teammate.activity.length))}/></footer></div>}</div><MorphingModal viewId={brief && teammate ? teammate.id : null} onClose={() => setBrief(false)} placement="center"><h3 className="font-medium">{teammate?.name} · Finished brief</h3><p className="mt-3 text-sm leading-relaxed">{teammate?.brief}</p><Button className="mt-4" onClick={() => setBrief(false)}>Close brief</Button></MorphingModal></MarketingFrame>;
}

export interface HeroVoiceNote { id: string; label: string; transcript: string; actions: MarketingLink[]; duration: string }
export interface VoiceMobileHeroProps extends MarketingHeading, MarketingSelectionProps {
  navigation: HeroNavigation; notes: HeroVoiceNote[]; download: MarketingLink;
  recording?: boolean;
  /** Without a recording adapter the recorder is explicitly a microphone-off presentation. */
  onRecordingChange?: (recording: boolean) => void | Promise<void>;
}
const voiceWaveform = withOccurrenceKeys([9, 14, 8, 20, 13, 26, 18, 12, 23, 14, 27, 10, 17, 12, 24, 16, 9, 22], String);

export function VoiceMobileHero({ navigation, notes, download, recording: controlledRecording, onRecordingChange, value, onValueChange, className, ...heading }: VoiceMobileHeroProps) {
  const [selected, select] = useMarketingSelection(notes.map(item => item.id), value, onValueChange);
  const note = notes.find(item => item.id === selected);
  const playback = useMarketingPlayback(3);
  const [localRecording, setLocalRecording] = useState(false);
  const [pending, setPending] = useState(false);
  const [notice, setNotice] = useState("");
  const [recordError, setRecordError] = useState("");
  const recordingBusy = useRef(false);
  const recording = controlledRecording ?? localRecording;
  const changeRecording = async () => {
    if (recordingBusy.current) return;
    const next = !recording;
    recordingBusy.current = true;
    setPending(true);
    setRecordError("");
    setNotice("");
    playback.setPlaying(false);
    try {
      await onRecordingChange?.(next);
      if (controlledRecording === undefined) setLocalRecording(next);
      if (!onRecordingChange) setNotice(next ? "Recording presentation only. Your microphone is off." : "Presentation stopped. No audio was recorded.");
    } catch (reason) {
      setRecordError(reason instanceof Error ? reason.message : "The recording adapter could not change state.");
    } finally {
      recordingBusy.current = false;
      setPending(false);
    }
  };
  return <MarketingFrame className={cn("py-4 sm:py-4 lg:py-4", className)}>
    <MarketingNav {...navigation}/>
    <div className="grid items-center gap-10 lg:grid-cols-2">
      <div className="px-3 py-8 sm:px-6 lg:px-12"><MarketingCopy {...heading}/><ButtonLink href={download.href} variant="outline" className="mt-5">↓ {download.label}</ButtonLink><p className="mt-10 border-t border-border pt-5 text-xs text-muted-foreground">✓ No typing required <span className="ml-4">✓ Private by default</span></p></div>
      <div ref={playback.ref} className="relative isolate flex min-h-[42rem] items-center overflow-hidden rounded-3xl bg-gradient-to-b from-emerald-100/70 to-orange-200/80 p-5 dark:from-emerald-950 dark:to-orange-950">
        <div aria-hidden className="absolute inset-x-0 top-1/4 -z-10 h-96 rotate-[-12deg] opacity-60 [background-image:radial-gradient(#d38b6b_1.2px,transparent_1.2px)] [background-size:5px_5px] [mask-image:radial-gradient(ellipse_at_center,black_30%,transparent_70%)]"/>
        <div className="mx-auto w-full max-w-80 rounded-[2rem] border-[7px] border-white/40 bg-background/80 p-4 shadow-[0_10px_40px_-20px_rgb(0_0_0/0.2)] backdrop-blur-xl">
          <div aria-hidden className="mx-auto mb-8 h-5 w-24 rounded-full bg-foreground"/>
          <div className="flex items-center justify-between gap-3"><h3 className="text-lg font-medium tracking-tight">Your voice, organized</h3><details className="relative"><summary aria-label="More options" className="grid size-9 cursor-pointer list-none place-items-center rounded-full hover:bg-background/70 focus-visible:outline-2">···</summary><div className="absolute right-0 top-10 z-20 w-48 rounded-xl border border-border bg-background p-2 shadow-sm"><button type="button" disabled={!note || recording} onClick={async () => { setRecordError(""); try { await navigator.clipboard.writeText(note?.transcript ?? ""); setNotice("Transcript copied to your clipboard."); } catch { setRecordError("Clipboard access was not available. Select the visible transcript to copy it."); } }} className="min-h-11 w-full rounded-lg px-3 text-left text-xs hover:bg-muted disabled:opacity-40 focus-visible:outline-2">Copy transcript</button><button type="button" disabled={recording} onClick={() => { playback.select(0); setNotice("Sample playback restarted."); }} className="min-h-11 w-full rounded-lg px-3 text-left text-xs hover:bg-muted disabled:opacity-40 focus-visible:outline-2">Restart sample</button><p className="px-3 py-2 text-[10px] leading-5 text-muted-foreground">{onRecordingChange ? "Recording uses your host adapter." : "Presentation only. No microphone connection."}</p></div></details></div>
          <div className="mt-5"><MarketingChoices label="Voice note" items={notes.map(item => ({ id: item.id, label: item.label }))} value={selected} onChange={id => { select(id); playback.select(0); }}/></div>
          {note ? <>
            <div className="mt-5 rounded-2xl border border-border/60 bg-background/40 p-4"><div className="flex items-center justify-between gap-3"><p className="text-[10px] text-muted-foreground">{note.duration} · Sample note</p><button type="button" disabled={recording} aria-label={playback.playing ? "Pause voice note" : "Play voice note"} aria-pressed={playback.playing} onClick={() => playback.setPlaying(!playback.playing)} className="grid size-9 place-items-center rounded-full bg-background disabled:opacity-40 focus-visible:outline-2">{playback.playing ? "Ⅱ" : "▷"}</button></div><div aria-hidden className="my-5 flex h-8 items-center justify-between gap-1">{voiceWaveform.map(({ item: height, key }) => <span key={key} className="w-1.5 rounded-full bg-foreground/60" style={{ height }}/>)}</div><p className="text-sm leading-7 text-muted-foreground">{playback.index === 1 ? `${note.transcript.slice(0, Math.ceil(note.transcript.length / 2))}…` : note.transcript}</p></div>
            {playback.index !== 1 && <div className="mt-4 rounded-2xl border border-border/60 bg-background/40 p-4"><p className="text-sm font-medium">Ready from your note</p><p className="mt-1 text-[10px] text-muted-foreground">{note.actions.length} actions found</p><ul className="mt-3">{note.actions.map(action => <li key={action.href}><a href={action.href} className="flex min-h-11 items-center gap-2 border-b border-border/50 py-2 text-xs last:border-0"><span aria-hidden>✓</span>{action.label}<span aria-hidden className="ml-auto">↗</span></a></li>)}</ul></div>}
            <p className="mt-3 text-[10px] text-muted-foreground">{["Ready actions", "Transcribing sample", "Transcript ready"][playback.index]}</p>
            {!recording && !pending && <PlaybackButtons playing={playback.playing} onToggle={() => playback.setPlaying(!playback.playing)} onRestart={() => playback.select(0)} onNext={() => playback.select((playback.index + 1) % 3)}/>}
          </> : <p className="mt-4 text-sm">No voice notes available.</p>}
          <div className="mt-4 flex items-center justify-between gap-3 rounded-full bg-background/70 py-1 pl-4 pr-1"><span className="text-[10px] text-muted-foreground">{recording ? onRecordingChange ? "Recording…" : "Presentation · microphone off" : "Say what’s next…"}</span><button type="button" aria-label={recording ? "Stop recording" : "Record a voice note"} aria-pressed={recording} disabled={pending || controlledRecording !== undefined && !onRecordingChange} onClick={changeRecording} className={cn("grid size-10 shrink-0 place-items-center rounded-full text-primary-foreground disabled:opacity-40 focus-visible:outline-2", recording ? "bg-destructive" : "bg-primary")}><span aria-hidden>{pending ? "◌" : recording ? "■" : <svg aria-hidden="true" viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.5"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/></svg>}</span></button></div>
          {notice && <p role="status" className="mt-3 text-[10px] leading-5 text-muted-foreground">{notice}</p>}{recordError && <p role="alert" className="mt-3 text-xs text-destructive">{recordError}</p>}
        </div>
      </div>
    </div>
  </MarketingFrame>;
}

export interface WorkflowAuroraHeroProps extends MarketingHeading { navigation: HeroNavigation; marks: MarketingMark[]; announcement?: MarketingLink }
const auroraColumns = Array.from({ length: 32 }, (_, index) => ({ x: index - 15.5, height: 170 + Math.pow(Math.abs(index - 15.5) / 15.5, 1.8) * 330 }));
export function WorkflowAuroraHero({ navigation, marks, announcement, className, ...heading }: WorkflowAuroraHeroProps) {
  return <MarketingFrame centered className={cn("min-h-[48rem] py-4 sm:min-h-[52rem] sm:py-4 lg:py-4", className)}><div aria-hidden className="pointer-events-none absolute inset-x-0 bottom-0 -z-10 flex h-[32rem] items-end overflow-hidden opacity-70 dark:opacity-40">{auroraColumns.map(column => <span key={column.x} className="h-full flex-1 border-r border-emerald-700/10 bg-gradient-to-t from-emerald-400 via-emerald-300/60 to-transparent" style={{ height: `${column.height}px` }}/>)}</div><MarketingNav {...navigation}/>{announcement && <a href={announcement.href} className="relative z-10 mb-6 inline-block rounded-full border border-border bg-background/70 px-4 py-2 text-xs">{announcement.label} →</a>}<MarketingCopy {...heading} className="mx-auto max-w-3xl pt-12 sm:pt-16"/><div className="relative mt-44 pb-8"><MarketingMarks marks={marks}/></div></MarketingFrame>;
}
export interface HeroBalancePeriod { id: string; label: string; balance: string; points: number[]; transactions: { id: string; label: string; amount: string; date: string }[] }
export interface HeroWalletRequest { kind: "deposit" | "transfer"; amount: string; recipient?: string }
export interface HeroWalletNotification { id: string; title: string; detail: string }
export interface DefiRoutingHeroProps extends MarketingHeading, MarketingSelectionProps {
  navigation: HeroNavigation; announcement: MarketingLink; periods: HeroBalancePeriod[];
  onRequestAccess: (email: string) => Promise<void>; custodyNote: string;
  account?: { name: string; address?: string; network?: string };
  notifications?: HeroWalletNotification[];
  /** Only the host can authorize or execute a request. Balances always remain host-owned. */
  onWalletRequest?: (request: HeroWalletRequest) => Promise<{ message: string }>;
}
function WalletRequestForm({ kind, onRequest }: { kind: HeroWalletRequest["kind"]; onRequest?: DefiRoutingHeroProps["onWalletRequest"] }) {
  const id = useId();
  const [amount, setAmount] = useState("");
  const [recipient, setRecipient] = useState("");
  const [draft, setDraft] = useState<HeroWalletRequest | null>(null);
  const [pending, setPending] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const busy = useRef(false);
  const editDraft = () => { setDraft(null); setSubmitted(false); setMessage(""); setError(""); };
  return <div>
    <h3 className="text-xl font-medium capitalize">{kind}</h3><p className="mt-3 text-sm leading-6 text-muted-foreground">{onRequest ? "Prepare a request for your wallet provider. Your provider owns authorization and execution." : "Presentation demo. Review a local draft; no wallet is connected and no funds move."}</p>
    <form className="mt-6 space-y-4" onSubmit={event => { event.preventDefault(); setError(""); if (!Number.isFinite(Number(amount)) || Number(amount) <= 0 || kind === "transfer" && !recipient.trim()) { setError("Enter a positive amount and a recipient address for transfers."); return; } setDraft({ kind, amount, ...(kind === "transfer" ? { recipient: recipient.trim() } : {}) }); }}>
      <div><label htmlFor={`${id}-amount`} className="mb-2 block text-sm">Amount</label><input id={`${id}-amount`} type="number" inputMode="decimal" min="0" step="any" required disabled={pending} value={amount} onChange={event => { setAmount(event.target.value); editDraft(); }} className="min-h-11 w-full rounded-xl border border-border bg-background px-3 text-sm focus-visible:outline-2"/></div>
      {kind === "transfer" && <div><label htmlFor={`${id}-recipient`} className="mb-2 block text-sm">Recipient address</label><input id={`${id}-recipient`} required disabled={pending} value={recipient} onChange={event => { setRecipient(event.target.value); editDraft(); }} className="min-h-11 w-full rounded-xl border border-border bg-background px-3 text-sm focus-visible:outline-2"/></div>}
      <Button type="submit" disabled={pending}>Review request</Button>
    </form>
    {draft && <div className="mt-5 rounded-xl border border-border bg-muted/30 p-4"><h4 className="text-sm font-medium">Request review</h4><dl className="mt-3 space-y-2 break-words text-sm"><div className="flex justify-between gap-4"><dt className="text-muted-foreground">Action</dt><dd className="capitalize">{draft.kind}</dd></div><div className="flex justify-between gap-4"><dt className="text-muted-foreground">Amount</dt><dd className="font-mono">{draft.amount}</dd></div>{draft.recipient && <div><dt className="text-muted-foreground">Recipient</dt><dd className="mt-1 font-mono text-xs">{draft.recipient}</dd></div>}</dl>{onRequest ? <Button className="mt-4" disabled={pending || submitted} onClick={async () => { if (busy.current) return; busy.current = true; setPending(true); setError(""); try { const response = await onRequest(draft); setMessage(response.message); setSubmitted(true); } catch (reason) { setError(reason instanceof Error ? reason.message : "The wallet provider rejected this request."); } finally { busy.current = false; setPending(false); } }}>{pending ? "Sending to host…" : submitted ? "Sent to host" : "Send request to host"}</Button> : <p role="status" className="mt-4 text-xs leading-6 text-muted-foreground">Local draft prepared. Nothing was submitted, signed, deposited, or transferred.</p>}</div>}
    {message && <p role="status" className="mt-4 text-sm leading-6">{message}</p>}{error && <p role="alert" className="mt-4 text-sm text-destructive">{error}</p>}
  </div>;
}
export function DefiRoutingHero({ navigation, announcement, periods, onRequestAccess, custodyNote, account, notifications = [], onWalletRequest, value, onValueChange, className, ...heading }: DefiRoutingHeroProps) {
  const [selected, select] = useMarketingSelection(periods.map(item => item.id), value, onValueChange);
  const [panel, setPanel] = useState<"profile" | "notifications" | "deposit" | "transfer" | null>(null);
  const [allTransactions, setAllTransactions] = useState(false);
  const period = periods.find(item => item.id === selected);
  const max = Math.max(1, ...(period?.points ?? []));
  return <MarketingFrame centered className={cn("py-4 sm:py-4 lg:py-4", className)}>
    <MarketingNav {...navigation}/><div className="mx-auto max-w-3xl pt-10"><a href={announcement.href} className="mb-6 inline-block rounded-full bg-muted px-3 py-1 text-xs text-muted-foreground">{announcement.label} →</a><MarketingCopy {...heading}/><div className="mx-auto max-w-md"><MarketingEmailCapture onSubmit={onRequestAccess} label="Join early access"/></div><p className="mt-2 text-xs text-muted-foreground">{custodyNote}</p></div>
    <div className="mx-auto mt-12 w-full max-w-80 rounded-[2rem] border-[7px] border-muted bg-background p-5 text-left shadow-[0_10px_40px_-30px_rgb(0_0_0/0.2)]">
      <div aria-hidden className="mx-auto mb-5 h-5 w-24 rounded-full bg-foreground"/>
      <div className="mb-6 flex items-center justify-between"><button type="button" aria-label="Open profile" onClick={() => setPanel("profile")} className="grid size-10 place-items-center rounded-full bg-muted text-xs focus-visible:outline-2">{account?.name.slice(0, 2).toUpperCase() || "◎"}</button><button type="button" aria-label="View notifications" onClick={() => setPanel("notifications")} className="relative grid size-10 place-items-center rounded-full text-muted-foreground hover:bg-muted focus-visible:outline-2"><svg aria-hidden="true" viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M6 9a6 6 0 0 1 12 0v5l2 3H4l2-3ZM10 21h4"/></svg>{notifications.length > 0 && <span className="absolute right-1 top-1 size-1.5 rounded-full bg-primary"/>}</button></div>
      <p className="text-xs text-muted-foreground">Total balance</p><p className="mt-2 font-mono text-3xl font-medium tracking-tight tabular-nums">{period?.balance ?? "—"}</p>
      {period && <svg role="img" aria-label={`${period.label} balance history: ${period.points.join(", ")}`} viewBox="0 0 240 130" className="my-6 h-40 w-full text-foreground"><polygon points={`0,125 ${period.points.map((point, i) => `${i * 240 / Math.max(1, period.points.length - 1)},${120 - Math.max(0, point) / max * 100}`).join(" ")} 240,125`} fill="currentColor" opacity="0.04"/><polyline points={period.points.map((point, i) => `${i * 240 / Math.max(1, period.points.length - 1)},${120 - Math.max(0, point) / max * 100}`).join(" ")} fill="none" stroke="currentColor" strokeWidth="1.8"/></svg>}
      <MarketingChoices label="Balance period" items={periods} value={selected} onChange={id => { select(id); setAllTransactions(false); }}/>
      {period && <><div className="mb-3 mt-6 flex items-center justify-between gap-3"><h3 className="text-sm font-medium">Transaction history</h3><button type="button" aria-expanded={allTransactions} disabled={period.transactions.length <= 3} onClick={() => setAllTransactions(current => !current)} className="min-h-11 text-[10px] text-muted-foreground hover:underline disabled:opacity-40 focus-visible:outline-2">{allTransactions ? "Show less" : "See all"}</button></div><ul>{(allTransactions ? period.transactions : period.transactions.slice(0, 3)).map(transaction => <li key={transaction.id} className="flex items-center justify-between gap-3 border-t border-border py-4 text-xs"><span>{transaction.label}<small className="mt-1 block text-[10px] text-muted-foreground">{transaction.date}</small></span><strong className="font-mono text-[10px] font-medium">{transaction.amount}</strong></li>)}</ul></>}
      <div className="mt-5 grid grid-cols-2 gap-2"><Button onClick={() => setPanel("deposit")}>Deposit</Button><Button variant="outline" onClick={() => setPanel("transfer")}>Transfer</Button></div>
    </div>
    <MorphingModal viewId={panel} onClose={() => setPanel(null)} placement="center"><div className="text-left">{panel === "profile" ? <><h3 className="text-xl font-medium">Account</h3><p className="mt-4 text-sm">{account?.name ?? "No connected account"}</p>{account?.address && <p className="mt-3 break-all font-mono text-xs text-muted-foreground">{account.address}</p>}{account?.network && <p className="mt-3 text-sm text-muted-foreground">{account.network}</p>}<p className="mt-5 text-xs leading-6 text-muted-foreground">{custodyNote}</p></> : panel === "notifications" ? <><h3 className="text-xl font-medium">Notifications</h3>{notifications.length ? <ul className="mt-5 divide-y divide-border">{notifications.map(item => <li key={item.id} className="py-4"><h4 className="text-sm font-medium">{item.title}</h4><p className="mt-2 text-sm leading-6 text-muted-foreground">{item.detail}</p></li>)}</ul> : <p className="mt-5 text-sm text-muted-foreground">No notifications.</p>}</> : panel && <WalletRequestForm key={panel} kind={panel} onRequest={onWalletRequest}/>}</div></MorphingModal>
  </MarketingFrame>;
}

export interface HeroSpecialist { id: string; label: string; prompt: string }
export interface HeroMatch { id: string; name: string; description: string; href: string }
export interface HeroMatchContext { files: readonly File[]; webSearch: boolean }
export interface AiMarketplaceHeroProps extends MarketingHeading {
  navigation: HeroNavigation; specialists: HeroSpecialist[]; prompts: string[];
  onMatch: (prompt: string, context?: HeroMatchContext) => Promise<HeroMatch[]>;
  files?: File[]; onFilesChange?: (files: File[]) => void;
  webSearch?: boolean; onWebSearchChange?: (enabled: boolean) => void;
}
export function AiMarketplaceHero({ navigation, specialists, prompts, onMatch, files: controlledFiles, onFilesChange, webSearch: controlledWebSearch, onWebSearchChange, className, ...heading }: AiMarketplaceHeroProps) {
  const promptId = useId();
  const fileInput = useRef<HTMLInputElement>(null);
  const [prompt, setPrompt] = useState("");
  const [promptIndex, setPromptIndex] = useState(0);
  const [localFiles, setLocalFiles] = useState<File[]>([]);
  const [localWebSearch, setLocalWebSearch] = useState(false);
  const [matches, setMatches] = useState<HeroMatch[]>([]);
  const [state, setState] = useState<"idle" | "pending" | "success" | "error">("idle");
  const [error, setError] = useState("");
  const busy = useRef(false);
  const files = controlledFiles ?? localFiles;
  const webSearch = controlledWebSearch ?? localWebSearch;
  const changeFiles = (next: File[]) => { if (controlledFiles === undefined) setLocalFiles(next); onFilesChange?.(next); };
  const changeWebSearch = () => { const next = !webSearch; if (controlledWebSearch === undefined) setLocalWebSearch(next); onWebSearchChange?.(next); };
  return <MarketingFrame centered className={cn("min-h-[100svh] bg-[#f5f7fb] py-4 sm:py-4 lg:py-4 dark:bg-[#17191e]", className)}>
    <MarketingAtmosphere kind="spectrum"/><MarketingNav {...navigation}/>
    <div data-marketing-copy className="mx-auto max-w-3xl pt-16 sm:pt-24">{heading.eyebrow && <p className="mb-7 text-xs text-muted-foreground">{heading.eyebrow}</p>}<h2>{heading.title}</h2><p className="mx-auto mt-6 max-w-2xl text-sm leading-7 text-muted-foreground sm:text-base">{heading.description}</p></div>
    <form className="relative z-10 mx-auto mt-8 max-w-3xl text-left" onSubmit={async event => { event.preventDefault(); if (busy.current) return; busy.current = true; setState("pending"); setError(""); setMatches([]); try { setMatches(await onMatch(prompt.trim(), { files, webSearch })); setState("success"); } catch (reason) { setError(reason instanceof Error ? reason.message : "Matching is unavailable. Please try again."); setState("error"); } finally { busy.current = false; } }}>
      <div className="rounded-3xl border border-white/40 bg-background/75 p-5 shadow-[0_5px_50px_-25px_rgb(0_0_0/0.1)] backdrop-blur-xl">
        <label htmlFor={promptId} className="mb-5 flex items-center gap-3 text-[10px] text-muted-foreground"><span aria-hidden className="grid size-7 place-items-center rounded-full bg-muted">✣</span>Auto-match a specialist</label>
        <textarea id={promptId} required value={prompt} disabled={state === "pending"} onChange={event => setPrompt(event.target.value)} placeholder={prompts[promptIndex] ?? "Describe your task"} className="min-h-20 w-full resize-y border-0 bg-transparent px-1 py-2 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring"/>
        {files.length > 0 && <ul aria-label="Attached files" className="my-3 flex flex-wrap gap-2">{withOccurrenceKeys(files, file => JSON.stringify([file.name, file.size, file.type, file.lastModified])).map(({ item: file, key }, index) => <li key={key} className="flex min-w-0 items-center gap-2 rounded-xl border border-border bg-background/75 py-1 pl-3 pr-1 text-[10px]"><span className="max-w-44 truncate">{file.name}</span><button type="button" aria-label={`Remove ${file.name}`} disabled={state === "pending" || controlledFiles !== undefined && !onFilesChange} onClick={() => changeFiles(files.filter((_, position) => position !== index))} className="grid size-8 place-items-center rounded-full hover:bg-muted disabled:opacity-40 focus-visible:outline-2">×</button></li>)}</ul>}
        <input ref={fileInput} type="file" multiple aria-label="Choose context files" className="hidden" onChange={event => { const selectedFiles = Array.from(event.currentTarget.files ?? []); if (selectedFiles.length) changeFiles([...files, ...selectedFiles]); event.currentTarget.value = ""; }}/>
        <div className="mt-3 flex items-center justify-between gap-2"><div className="flex items-center gap-1">
          <button type="button" aria-label="Attach a file" disabled={state === "pending" || controlledFiles !== undefined && !onFilesChange} onClick={() => fileInput.current?.click()} className="grid size-10 place-items-center rounded-full text-muted-foreground hover:bg-muted disabled:opacity-40 focus-visible:outline-2"><svg aria-hidden="true" viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="m8 12 6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l9-9M7 13l7-7"/></svg></button>
          <button type="button" aria-label="Search the web" aria-pressed={webSearch} disabled={state === "pending" || controlledWebSearch !== undefined && !onWebSearchChange} onClick={changeWebSearch} className={cn("grid size-10 place-items-center rounded-full disabled:opacity-40 focus-visible:outline-2", webSearch ? "bg-primary/10 text-primary" : "text-muted-foreground hover:bg-muted")}><svg aria-hidden="true" viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.5"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/></svg></button>
          <Button type="button" size="sm" variant="ghost" disabled={!prompts.length || state === "pending"} onClick={() => { setPrompt(prompts[promptIndex] ?? ""); setPromptIndex((promptIndex + 1) % Math.max(1, prompts.length)); }}>Try a prompt</Button>
        </div><button type="submit" aria-label="Match a specialist" disabled={!prompt.trim() || state === "pending"} className="grid size-10 shrink-0 place-items-center rounded-full bg-foreground text-background disabled:opacity-40 focus-visible:outline-2">{state === "pending" ? "◌" : "↑"}</button></div>
        {webSearch && <p className="mt-2 text-[10px] text-muted-foreground">Web search will be requested from your matching provider.</p>}
      </div>
      <div className="mt-3 flex flex-wrap justify-center gap-2">{specialists.map(item => <button type="button" key={item.id} disabled={state === "pending"} onClick={() => setPrompt(item.prompt)} className="min-h-11 rounded-full border border-border/30 bg-background/60 px-3 text-[10px] text-muted-foreground focus-visible:outline-2">{item.label}</button>)}</div>
      <p role={state === "error" ? "alert" : "status"} className="mt-3 text-center text-sm text-muted-foreground">{state === "error" ? error : state === "pending" ? "Matching your task to available specialists." : state === "success" ? matches.length ? `${matches.length} specialists found` : "No specialists match this task. Try a different brief." : ""}</p>
      <ul className="mt-3 space-y-2">{matches.map(match => <li key={match.id}><a href={match.href} className="block rounded-xl border border-border bg-background/90 p-3"><strong className="text-sm font-medium">{match.name} ↗</strong><p className="mt-1 text-xs text-muted-foreground">{match.description}</p></a></li>)}</ul>
    </form>
    <div className="relative z-10 mt-8 flex flex-wrap justify-center gap-5 text-xs text-muted-foreground"><a href={heading.primary.href} className="inline-flex min-h-11 items-center hover:underline">{heading.primary.label} ↗</a>{heading.secondary && <a href={heading.secondary.href} className="inline-flex min-h-11 items-center hover:underline">{heading.secondary.label}</a>}</div>
  </MarketingFrame>;
}
export interface SignalAuroraHeroProps extends MarketingHeading { navigation: HeroNavigation; marks: MarketingMark[]; signal: { label: string; value: string; detail: string } }
export function SignalAuroraHero({ navigation, marks, signal, className, ...heading }: SignalAuroraHeroProps) {
  return <MarketingFrame className={cn("min-h-[760px]", className)}><MarketingAtmosphere webgl/><MarketingNav {...navigation}/><div className="max-w-3xl py-10"><MarketingCopy {...heading}/><aside className="relative z-10 mt-8 inline-flex max-w-lg items-center gap-4 rounded-2xl border border-border/50 bg-background/40 p-4 backdrop-blur-xl"><strong className="text-2xl font-medium tracking-tight">{signal.value}</strong><div><p className="text-xs font-medium">{signal.label}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{signal.detail}</p></div></aside></div><MarketingMarks marks={marks} moving/></MarketingFrame>;
}
export interface WorkflowSplitHeroProps extends MarketingHeading, MarketingSelectionProps { navigation?: HeroNavigation; marks: MarketingMark[]; onRequestAccess: (email: string) => Promise<void>; dashboards: { id: string; label: string; metrics: HeroMetric[]; tasks: { id: string; name: string; status: string; detail: string }[] }[] }
export function WorkflowSplitHero({ navigation, marks, onRequestAccess, dashboards, value, onValueChange, className, ...heading }: WorkflowSplitHeroProps) {
  const [selected, select] = useMarketingSelection(dashboards.map(item => item.id), value, onValueChange);
  const [taskId, setTaskId] = useState<string | null>(null);
  const dashboard = dashboards.find(item => item.id === selected);
  const task = dashboard?.tasks.find(item => item.id === taskId);
  return <MarketingFrame className={className}>{navigation && <MarketingNav {...navigation}/>}<div className="mx-auto grid max-w-6xl items-center gap-12 lg:grid-cols-[1fr_1.15fr] lg:gap-8"><div><MarketingCopy {...heading}/><MarketingEmailCapture onSubmit={onRequestAccess}/><MarketingMarks marks={marks} moving/></div><Card className="overflow-hidden rounded-3xl bg-background shadow-[0_20px_80px_-50px_rgb(0_0_0/0.2)]"><CardHeader><CardTitle as="h3">Operations overview</CardTitle><MarketingChoices label="Operations dashboard" items={dashboards} value={selected} onChange={id => { select(id); setTaskId(null); }}/></CardHeader><CardContent className="space-y-4">{dashboard ? <><MetricStrip metrics={dashboard.metrics}/><div className="rounded-xl border border-border p-4"><h4 className="mb-4 text-xs font-medium">Active work</h4>{dashboard.tasks.map(item => <button key={item.id} type="button" aria-expanded={taskId === item.id} onClick={() => setTaskId(taskId === item.id ? null : item.id)} className="flex min-h-11 w-full items-center justify-between gap-3 border-t border-border py-3 text-left text-xs"><span>{item.name}</span><span className="text-[10px] text-muted-foreground">{item.status} ↗</span></button>)}</div>{task && <div role="status" className="rounded-xl bg-muted p-4 text-sm"><h4 className="font-medium">{task.name}</h4><p className="mt-1 text-muted-foreground">{task.detail}</p></div>}</> : <p>No dashboard data available.</p>}</CardContent></Card></div></MarketingFrame>;
}
export interface HeroIncident { id: string; label: string; time: string; detail: string; messages: { author: string; text: string }[] }
export interface AgentCenteredHeroProps extends MarketingHeading, MarketingSelectionProps { incidents: HeroIncident[] }
export function AgentCenteredHero({ incidents, value, onValueChange, className, ...heading }: AgentCenteredHeroProps) {
  const [selected, select] = useMarketingSelection(incidents.map(item => item.id), value, onValueChange);
  const incident = incidents.find(item => item.id === selected);
  const playback = useMarketingPlayback(incident?.messages.length ?? 0);
  return <MarketingFrame centered className={className}><MarketingCopy {...heading} className="mx-auto max-w-3xl [&_h2]:text-foreground [&_h2>span:first-child]:text-muted-foreground"/><div ref={playback.ref} className="relative mt-12 grid gap-5 overflow-hidden rounded-3xl bg-gradient-to-br from-blue-100/80 via-cyan-100/50 to-stone-100/70 p-5 pt-16 text-left sm:grid-cols-2 sm:p-10 sm:pt-24 dark:from-blue-950/50 dark:via-cyan-950/30 dark:to-stone-900/50"><MarketingAtmosphere kind="grain"/><Card className="bg-background/70 backdrop-blur-xl"><CardHeader><CardTitle as="h3">Incident timeline</CardTitle></CardHeader><CardContent><ol className="space-y-3 border-l border-border pl-4">{incidents.map(item => <li key={item.id}><button type="button" aria-pressed={item.id === selected} onClick={() => { select(item.id); playback.select(0); }} className={cn("w-full rounded-xl border p-3 text-left text-sm", item.id === selected ? "border-primary bg-muted" : "border-transparent")}><span className="block text-xs text-muted-foreground">{item.time}</span>{item.label}</button></li>)}</ol>{incident && <p className="mt-4 text-sm text-muted-foreground">{incident.detail}</p>}</CardContent></Card><Card className="bg-background/70 backdrop-blur-xl"><CardHeader><CardTitle as="h3">Agent conversation</CardTitle><CardDescription>Sample incident review</CardDescription></CardHeader><CardContent><ol className="space-y-3">{withOccurrenceKeys(incident?.messages ?? [], message => JSON.stringify([message.author, message.text])).slice(0, playback.index + 1).map(({ item: message, key }) => <li key={key} className="rounded-xl bg-muted/70 p-3 text-sm"><strong className="block text-xs">{message.author}</strong>{message.text}</li>)}</ol><PlaybackButtons playing={playback.playing} onToggle={() => playback.setPlaying(!playback.playing)} onRestart={() => playback.select(0)} onNext={() => playback.select((playback.index + 1) % Math.max(1, incident?.messages.length ?? 0))}/></CardContent></Card></div></MarketingFrame>;
}

export interface HeroCodeSample { id: string; label: string; request: string; response: string; language: string }
export interface CodeDemoHeroProps extends MarketingHeading, MarketingSelectionProps { promotion: MarketingLink; samples: HeroCodeSample[]; scenery?: ReactNode }
export function CodeDemoHero({ promotion, samples, scenery, value, onValueChange, className, ...heading }: CodeDemoHeroProps) {
  const [selected, select] = useMarketingSelection(samples.map(item => item.id), value, onValueChange);
  const sample = samples.find(item => item.id === selected);
  const playback = useMarketingPlayback(3);
  const [copyState, setCopyState] = useState("");
  return <MarketingFrame className={className}><a href={promotion.href} className="mb-6 inline-block rounded-full border border-border px-4 py-2 text-xs text-muted-foreground">{promotion.label} →</a><MarketingCopy {...heading} className="max-w-6xl lg:grid lg:grid-cols-2 lg:gap-x-10 lg:space-y-0 [&_h2]:lg:col-start-1 [&_h2]:lg:row-span-3 [&_p]:lg:col-start-2 [&_div]:lg:col-start-2"/><div ref={playback.ref} className="relative mt-12 min-h-[30rem] overflow-hidden rounded-3xl border border-border bg-gradient-to-b from-stone-700 to-amber-900 p-4 pt-16 sm:p-12 sm:pt-24"><div aria-hidden="true" className="absolute inset-0 bg-[radial-gradient(ellipse_at_bottom,#8f7354,transparent_65%)] opacity-60">{scenery ?? <svg aria-hidden="true" focusable="false" viewBox="0 0 1000 500" preserveAspectRatio="xMidYMid slice" className="size-full"><circle cx="760" cy="95" r="55" fill="currentColor" opacity="0.15"/><path d="M0 400 210 120 400 360 620 90 1000 430V500H0Z" fill="currentColor" opacity="0.08"/><path d="M0 460 330 260 500 420 800 230 1000 400V500H0Z" fill="currentColor" opacity="0.13"/></svg>}</div><div className="relative mx-auto max-w-4xl rounded-2xl border border-white/20 bg-neutral-950/85 p-4 text-white shadow-xl backdrop-blur-xl sm:p-6 [&_button]:border-white/20 [&_button]:text-white"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><MarketingChoices label="Code sample" items={samples} value={selected} onChange={id => { select(id); playback.select(0); setCopyState(""); }}/><span className="text-xs text-background/60">Sample transcript · no request sent</span></div>{sample ? <><p className="mb-2 text-xs">{sample.language} request</p><pre className="overflow-x-auto whitespace-pre-wrap break-words text-xs leading-relaxed text-background">{sample.request}</pre>{playback.index > 0 && <><p className="mb-2 mt-5 text-xs">Response</p><pre className="overflow-x-auto whitespace-pre-wrap break-words text-xs leading-relaxed text-background/80">{playback.index === 1 ? `${sample.response.slice(0, Math.ceil(sample.response.length / 2))}▍` : sample.response}</pre></>}<div className="mt-4 flex flex-wrap items-center gap-3"><Button size="sm" variant="secondary" onClick={async () => { try { if (!navigator.clipboard) throw new Error("Clipboard unavailable"); await navigator.clipboard.writeText(sample.request); setCopyState("Request copied"); } catch { setCopyState("Copy unavailable. Select the request text to copy."); } }}>Copy request</Button><span role="status" className="text-xs">{copyState}</span></div></> : <p>No code samples available.</p>}<PlaybackButtons playing={playback.playing} onToggle={() => playback.setPlaying(!playback.playing)} onRestart={() => playback.select(0)} onNext={() => playback.select((playback.index + 1) % 3)}/></div></div></MarketingFrame>;
}
export interface HeroKnowledgeAnswer { id: string; question: string; steps: { title: string; text: string; citation: MarketingLink }[] }
export interface CenteredDemoHeroProps extends MarketingHeading, MarketingSelectionProps { answers: HeroKnowledgeAnswer[] }
export function CenteredDemoHero({ answers, value, onValueChange, className, ...heading }: CenteredDemoHeroProps) {
  const [selected, select] = useMarketingSelection(answers.map(item => item.id), value, onValueChange);
  const answer = answers.find(item => item.id === selected);
  const playback = useMarketingPlayback(answer?.steps.length ?? 0);
  return <MarketingFrame centered className={className}><MarketingCopy {...heading} className="mx-auto max-w-3xl"/><div ref={playback.ref} className="relative mt-10 overflow-hidden rounded-3xl bg-muted/30 p-5 sm:p-10"><MarketingAtmosphere kind="grain"/><Card className="relative mx-auto max-w-2xl bg-background/75 text-left shadow-xl backdrop-blur-xl"><CardHeader><CardTitle as="h3">Ask your knowledge base</CardTitle><MarketingChoices label="Knowledge question" items={answers.map(item => ({ id: item.id, label: item.question }))} value={selected} onChange={id => { select(id); playback.select(0); }}/></CardHeader><CardContent>{answer ? <ol className="space-y-5">{answer.steps.slice(0, playback.index + 1).map((step, index) => <li key={step.title}><h4 className="text-sm font-semibold">{index + 1}. {step.title}</h4><p className="my-2 text-sm leading-relaxed text-muted-foreground">{step.text}</p><a href={step.citation.href} className="text-xs underline underline-offset-4">[{index + 1}] {step.citation.label}</a></li>)}</ol> : <p>No answers available.</p>}<p className="mt-4 text-xs text-muted-foreground">Cited answer · sample playback</p><PlaybackButtons playing={playback.playing} onToggle={() => playback.setPlaying(!playback.playing)} onRestart={() => playback.select(0)} onNext={() => playback.select((playback.index + 1) % Math.max(1, answer?.steps.length ?? 0))}/></CardContent></Card></div></MarketingFrame>;
}
export interface CenteredMarqueeHeroProps extends MarketingHeading { marks: MarketingMark[] }
export function CenteredMarqueeHero({ marks, className, ...heading }: CenteredMarqueeHeroProps) {
  return <MarketingFrame centered className={className}><div className="mx-auto max-w-3xl pb-10"><MarketingCopy {...heading}/></div><MarketingMarks marks={marks} moving/></MarketingFrame>;
}
